/**
 * Copia el comando capturado y publica feedback sólo mientras siga vigente.
 * @param {{readText:()=>string, clipboard:{writeText:(text:string)=>Promise<void>},
 * onStatus:(state:'success'|'error')=>void, setBusy:(busy:boolean)=>void}} adapters
 * @returns {Promise<void>} Termina después de liberar el estado busy.
 * Los errores de Clipboard se convierten en feedback recuperable.
 */
export async function copyCommand({readText, clipboard, onStatus, setBusy}) {
  const text = readText();
  setBusy(true);
  try {
    await clipboard.writeText(text);
    if (readText() === text) onStatus('success');
  } catch {
    if (readText() === text) onStatus('error');
  } finally {
    setBusy(false);
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {copyCommand} from '../src/copy-command.mjs';

test('copia exactamente el comando y libera busy', async()=>{
  const command='npx --yes omni-spec@preview init';
  let copied; const status=[]; const busy=[];
  await copyCommand({readText:()=>command,clipboard:{writeText:async text=>{copied=text;}},onStatus:s=>status.push(s),setBusy:b=>busy.push(b)});
  assert.equal(copied,command);assert.deepEqual(status,['success']);assert.deepEqual(busy,[true,false]);
});
test('rechazo del portapapeles informa error recuperable y libera busy',async()=>{
  const status=[];const busy=[];
  await copyCommand({readText:()=>'/omni-init',clipboard:{writeText:async()=>{throw new Error('denied');}},onStatus:s=>status.push(s),setBusy:b=>busy.push(b)});
  assert.deepEqual(status,['error']);assert.deepEqual(busy,[true,false]);
});
for (const reject of [false,true]) test('descarta '+(reject?'rechazo':'éxito')+' tardío de un comando anterior',async()=>{
  let command='/omni-init',finish;const status=[];const busy=[];let copied;
  const pending=copyCommand({readText:()=>command,clipboard:{writeText:text=>{copied=text;return new Promise((resolve,fail)=>{finish=reject?()=>fail(new Error('denied')):resolve;});}},onStatus:s=>status.push(s),setBusy:b=>busy.push(b)});
  command='$omni-init';finish();await pending;
  assert.equal(copied,'/omni-init');assert.deepEqual(status,[]);assert.deepEqual(busy,[true,false]);
});

